export function getBlock(id: BlockType): BlockData {
  return BLOCKS[id] || BLOCKS[BlockType.AIR];
}

export function isTransparent(id: BlockType): boolean {
  return BLOCKS[id]?.transparent ?? true;
}

export function isSolid(id: BlockType): boolean {
  return BLOCKS[id]?.solid ?? false;
}

export function isLiquid(id: BlockType): boolean {
  return BLOCKS[id]?.liquid ?? false;
}
